-- AI franchise owners: bot seats that bid through the same authoritative engine.
-- Generated by scripts/gen-ai-migration.mjs (function bodies are copied from earlier migrations).

-- Bots are profiles without a login.
alter table public.profiles drop constraint profiles_id_fkey;
alter table public.profiles add column is_bot boolean not null default false;

alter table public.room_members add column bot_persona text
  check (bot_persona is null or bot_persona in ('aggressive', 'value', 'star', 'youth', 'balanced'));
alter table public.room_settings
  add column ai_difficulty text not null default 'normal' check (ai_difficulty in ('easy', 'normal', 'hard')),
  add column ai_autofill_sec int check (ai_autofill_sec is null or ai_autofill_sec between 15 and 600),
  add column ai_autofill_at timestamptz;
alter table public.auction_sessions add column next_bot_at timestamptz;

-- Scouting ratings (0-100). First seeded from base price, last price and caps; a later
-- pipeline can overwrite them with ball-by-ball data (source changes accordingly).
create table public.player_ratings (
  player_id uuid primary key references public.players (id) on delete cascade,
  overall int not null check (overall between 0 and 100),
  batting int check (batting between 0 and 100),
  bowling int check (bowling between 0 and 100),
  form int not null default 50 check (form between 0 and 100),
  tags text[] not null default '{}',
  stats jsonb not null default '{}'::jsonb,
  note text,
  source text not null default 'prior',
  updated_at timestamptz not null default now()
);
alter table public.player_ratings enable row level security;
create policy player_ratings_read on public.player_ratings for select to authenticated, anon using (true);

insert into public.player_ratings (player_id, overall, tags, source)
select p.id,
  greatest(25, least(95, round(
    case when ps.last_price_lakh is not null and ps.last_price_lakh > 0
      then 0.6 * (30 + 13.5 * ln(ps.last_price_lakh / 20.0)) + 0.4 * b.base_r
      else b.base_r end
    + case when p.is_capped then 3 else 0 end
    + case when ps.is_marquee then 4 else 0 end))::int),
  array_remove(array[
    case p.role when 'WK' then 'keeper' when 'BWL' then 'bowler' when 'BAT' then 'batter' else 'allrounder' end,
    case when p.is_overseas then 'overseas' end,
    case when not p.is_capped then 'uncapped' end
  ], null),
  'prior'
from public.players p
join public.player_seasons ps on ps.player_id = p.id
join public.seasons s on s.id = ps.season_id and s.is_active
cross join lateral (select case
    when ps.base_price_lakh >= 200 then 72 when ps.base_price_lakh >= 150 then 64
    when ps.base_price_lakh >= 100 then 56 when ps.base_price_lakh >= 75 then 50
    when ps.base_price_lakh >= 50 then 44 else 38 end as base_r) b
on conflict (player_id) do nothing;

create function public._bot_hash(p_text text)
returns float8 language sql immutable set search_path = public as $$
  select (abs(hashtext(p_text)::bigint) % 10000) / 10000.0;
$$;
